def count_positive(numbers):
    count = 0
    for num in numbers:
        if num > 0:
            count += 1
    return count

def count_frequency(list_of_lists):
    frequency = {}
    for sublist in list_of_lists:
        for item in sublist:
            if item in frequency:
                frequency[item] += 1
            else:
                frequency[item] = 1
    return frequency
